// Structural + Handler-specific validation of the Finance Inbox Request
// Contract this workflow receives from the Intent Router (ADR-0008 Decision
// 1, docs/workflows/finance-inbox-contract.md). The Router already did
// contract-shape validation before dispatching here -- this re-validates
// defensively (this workflow could also be called directly by a future
// UPLOAD_RECEIPT handler reusing this same write path, per ADR-0008
// Decision 3's Handler ID table) and adds ONE Handler-specific rule the
// shared contract does not: source.externalUserId is REQUIRED (not just
// nullable) by the Eyan Finance Service API's createExpenseAutomatedValidator
// (eyan-ai-platform finance-automation.validator.ts) -- without it, this
// Handler cannot safely attribute an expense to anyone, so it fails closed
// here rather than sending a request the Finance API would reject anyway.
const req = $json || {};
const reasons = [];

function requireNonEmptyString(field) {
  if (typeof req[field] !== 'string' || req[field].trim().length === 0) {
    reasons.push(`Missing/empty required field: ${field}.`);
  }
}

requireNonEmptyString('contractVersion');
requireNonEmptyString('workflowExecutionId');
requireNonEmptyString('workflowName');
requireNonEmptyString('channel');

if (typeof req.rawText !== 'string') {
  reasons.push('rawText must be a string (may be empty).');
}

if (!Array.isArray(req.attachments)) {
  reasons.push('attachments must be an array.');
}

// Handler-specific -- see comment above. The shared Inbox Contract allows
// externalUserId to be null; this Handler cannot.
if (typeof req.externalUserId !== 'string' || req.externalUserId.trim().length === 0) {
  reasons.push('Missing externalUserId -- cannot attribute this expense to a sender.');
}

return [{
  json: {
    valid: reasons.length === 0,
    reason: reasons.join(' '),
    contractVersion: req.contractVersion,
    workflowExecutionId: req.workflowExecutionId,
    workflowName: req.workflowName,
    channel: req.channel,
    externalUserId: req.externalUserId ?? null,
    externalMessageId: req.externalMessageId ?? null,
    rawText: typeof req.rawText === 'string' ? req.rawText : '',
    attachments: Array.isArray(req.attachments) ? req.attachments : [],
    startedAt: Date.now(),
  },
}];

// Orchestration-layer rejection (malformed/incomplete envelope) -- not a
// Finance business decision (e.g. not "ambiguous expense"), so this never
// asks a clarifying question -- same posture as the Router's own
// "Build Contract Violation Response" (ADR-0008 Decision 2). intent stays
// CREATE_EXPENSE (not UNRECOGNIZED): the Router already classified this
// correctly before dispatching here, and ADR-0008 Decision 2 requires
// intent to be present even on error, for audit/logging.
const v = $json;

return [{
  json: {
    contractVersion: '1',
    workflowExecutionId: v.workflowExecutionId || 'unknown',
    status: 'error',
    intent: 'CREATE_EXPENSE',
    message: "Sorry, I couldn't process that message. Please try again.",
    data: null,
    clarifyingQuestion: null,
  },
}];

// Builds the Ollama /api/chat request body for expense-field extraction.
// The Router deliberately extracts nothing beyond {intent, confidence}
// (ADR-0008 Notes amendment) -- amount/category/paymentMethod/date/
// description/isRecurring extraction is entirely this Handler's job, the first place
// in the AI Finance Inbox chain that does it.
//
// format: 'json' is Ollama's own native JSON-mode flag -- NOT n8n's
// LangChain Agent/outputParserStructured stack the Finance Intent Router
// uses. See docs/adrs/ADR-0011-finance-handler-ai-extraction-approach.md:
// that stack wraps structured output in a format_final_json_response
// tool-call envelope this n8n/LangChain version does not unwrap (0%
// structured-output success rate across both locally available
// tool-capable models, docs/adrs/ADR-0009-finance-intent-router-model-selection.md).
// This node instead calls Ollama's REST API directly and "Validate Expense
// Extraction" parses its plain JSON response text -- the same
// direct-httpRequest-plus-manual-parse pattern already established in
// workflows/crm/03-ai-qualification.json's "Call AI Core"/"Map AI Core
// Result" pair, applied here against local Ollama instead of a remote AI
// Core capability, since no Finance extraction capability exists in AI Core.
//
// model is hardcoded to gemma3:4b -- this Handler's own production-capacity
// finding on this VPS (~11 GiB RAM + 8 GiB swap), independent of the
// Router's mistral:7b choice (ADR-0009 is a Router-specific evaluation, not
// binding on this Handler -- see ADR-0011's Addendum). gemma3:4b lacks
// Ollama "tools" capability, which is exactly why ADR-0009 excludes it for
// the Router's ToolsAgent-based Agent node -- that exclusion does not apply
// here, since this Handler never uses an Agent node, only a direct
// httpRequest call against Ollama's native /api/chat JSON mode (ADR-0011
// Decision, pattern 2), which gemma3:4b handles correctly. NOT read from
// $env.OLLAMA_MODEL, which is a different, CRM-era config value (currently
// qwen2.5-coder:7b, unused by any workflow since Sprint 5's AI Core
// migration) that must not be silently inherited by an unrelated domain.
//
// options.temperature: 0 and options.num_ctx: 2048 are both production
// test findings on this VPS: temperature 0 for deterministic extraction,
// and num_ctx 2048 substantially outperforms Ollama's 4096 default for
// this workload (a single short message, not a large context need).
//
// today: no message-received timestamp survives to this Handler -- the
// Finance Inbox Contract deliberately excludes channel-specific timestamps
// (e.g. Slack's receivedAt) from the Router payload (ADR-0008 Decision 4's
// "no channel-metadata bag" rule). This workflow's own execution time
// resolves relative dates ("today", "yesterday") and is the fallback when
// no date is mentioned at all -- an ordinary chat-expense-logger
// convention, NOT the same class of "invented data" the amount/category
// clarification rules exist to prevent (those guard against guessing a
// fact the user disagrees with; defaulting an undated casual mention to
// today is the ordinary reading of the message).
const input = $('Validate Handler Input').item.json;
const today = new Date().toISOString().slice(0, 10);

const attachmentNote = (input.attachments && input.attachments.length)
  ? `\n[This message includes ${input.attachments.length} attachment(s).]`
  : '';

const systemPrompt = `You are the Finance CREATE_EXPENSE Handler's expense-field extractor for the AI Finance Inbox. Your ONLY job is to read the user's raw message and extract the fields needed to log an expense. Intent classification is already done (this message was already routed here as CREATE_EXPENSE) -- you do not classify intent, do not answer questions, and have no access to any Finance data.

Extract exactly these fields:

- amount: the numeric amount spent, as a plain number (e.g. 12.50). null if no amount is mentioned or it cannot be determined -- NEVER invent or guess a number.
- category: EXACTLY one of these values: HOUSING, FOOD, UTILITIES, TRANSPORTATION, SHOPPING, MEDICAL, CREDIT_CARD, SAVINGS, TAX, OTHERS. No other value is valid -- for example, "Food & Drink" is NOT a valid category; the closest real value is FOOD. null if the category cannot be confidently determined -- NEVER guess between two plausible categories, and NEVER invent a category value that is not in this exact list.
- paymentMethod: EXACTLY one of these values, or null if not mentioned: CASH, CREDIT_CARD, DEBIT_CARD, BANK_TRANSFER, OTHER. No other value is valid -- for example, "Imagin Card" is NOT a valid paymentMethod. Named cards and payment instruments ("Imagin", "Visa", "Mastercard", "Amex", "Revolut", or similar) are not paymentMethod values themselves -- when the message names one of these to describe how something was paid, map it to CREDIT_CARD, unless the message specifically says it is a debit card, in which case use DEBIT_CARD.
- date: the date the expense occurred, as YYYY-MM-DD. "today" is NOT a valid date output -- always resolve it to an actual calendar date. If the message implies today (or gives no date at all), use ${today}. If it says "yesterday", use the day before ${today}. Use your best resolution of any other relative or explicit date mentioned.
- description: a short (under 100 characters) plain-text description of what the expense was for, drawing on the message's own wording (e.g. merchant, item). null if the message gives nothing beyond the amount.
- isRecurring: true ONLY if the message clearly and explicitly describes a repeating or recurring expense (e.g. "my monthly Netflix subscription", "rent, same as every month", "this happens every month"). false if the message describes a one-time expense, or does not mention recurrence at all. NEVER guess true from an ambiguous or unstated case -- default to false.

Note: "CREDIT_CARD" appears as a value in BOTH category and paymentMethod -- they are two separate fields. A message about paying a credit card BILL is category CREDIT_CARD; a message about paying an unrelated expense BY credit card is paymentMethod CREDIT_CARD (with category describing what was bought).

Output rules -- follow every one of these exactly:
- Never invent an amount. If it cannot be determined, use null.
- Never invent a category. If it cannot be confidently determined, use null -- do not pick the closest guess.
- Never output markdown, code fences, or any text other than the JSON object.
- Return exactly one JSON object with exactly these six keys (amount, category, paymentMethod, date, description, isRecurring) and no other text, no explanation.`;

return [{
  json: {
    ...input,
    today,
    ollamaRequestBody: {
      model: 'gemma3:4b',
      format: 'json',
      stream: false,
      options: {
        temperature: 0,
        num_ctx: 2048,
      },
      messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user', content: `Message: ${input.rawText}${attachmentNote}` },
      ],
    },
  },
}];

// Distinguishes the failure classes this Handler's Failure Handling scope
// requires kept separate: (1) the Ollama call itself failed -- network/
// timeout, surfaced via "Call Ollama - Extract Expense"'s
// onError: continueRegularOutput as $json.error, same pattern as the
// Router's own "Validate Agent Output"; (2) Ollama responded but the
// content isn't valid/parseable JSON at all -- also a system/model
// reliability failure, not a user-facing ambiguity; (3) Ollama responded
// with valid JSON but couldn't confidently determine amount and/or
// category -- THIS is the only case that becomes a clarifying question,
// never (1) or (2), which become a safe generic error instead.
const EXPENSE_CATEGORIES = ['HOUSING', 'FOOD', 'UTILITIES', 'TRANSPORTATION', 'SHOPPING', 'MEDICAL', 'CREDIT_CARD', 'SAVINGS', 'TAX', 'OTHERS'];
const PAYMENT_METHODS = ['CASH', 'CREDIT_CARD', 'DEBIT_CARD', 'BANK_TRANSFER', 'OTHER'];

const context = $('Prepare Expense Extraction Input').item.json;
const today = context.today;

function fail(reasonCode) {
  return [{
    json: {
      ...context,
      extractionOutcome: 'extraction_failed',
      reasonCode,
    },
  }];
}

if ($json && $json.error) {
  const message = String(($json.error && $json.error.message) || $json.error);
  console.log(`[Validate Expense Extraction] Ollama call failed: ${message}`);
  return fail('ollama_call_failed');
}

let extracted;
try {
  const content = $json && $json.message && $json.message.content;
  extracted = typeof content === 'string' ? JSON.parse(content) : null;
} catch (error) {
  extracted = null;
}

if (!extracted || typeof extracted !== 'object') {
  console.log('[Validate Expense Extraction] Ollama response was not parseable JSON.');
  return fail('unparseable_output');
}

// amount -- accept a number or a numeric string, never invent one
const rawAmount = extracted.amount;
const amount = (typeof rawAmount === 'number' && Number.isFinite(rawAmount))
  ? rawAmount
  : (typeof rawAmount === 'string' && rawAmount.trim() !== '' && Number.isFinite(Number(rawAmount)))
    ? Number(rawAmount)
    : null;
const amountValid = amount !== null && amount > 0;

// category -- must be a real ExpenseCategory value, never guessed
const category = (typeof extracted.category === 'string' && EXPENSE_CATEGORIES.includes(extracted.category))
  ? extracted.category
  : null;

// paymentMethod -- optional; an invalid/unrecognized value is treated as
// "not provided", never blocks the expense (the Finance API itself treats
// this field as optional)
const paymentMethod = (typeof extracted.paymentMethod === 'string' && PAYMENT_METHODS.includes(extracted.paymentMethod))
  ? extracted.paymentMethod
  : undefined;

// date -- defaults to today when absent/invalid; see "Prepare Expense
// Extraction Input"'s comment on why this default is not the same class of
// "invented data" as amount/category.
const dateValid = typeof extracted.date === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(extracted.date) && !Number.isNaN(Date.parse(extracted.date));
const date = dateValid ? extracted.date : today;

const description = (typeof extracted.description === 'string' && extracted.description.trim())
  ? extracted.description.trim().slice(0, 500)
  : undefined;

// isRecurring -- optional, defaults to false. Only a literal boolean true
// is honored; anything else (missing, null, a non-boolean value) is
// treated as false, never blocking the expense and never guessed true --
// matches the extraction prompt's own "NEVER guess true from an ambiguous
// or unstated case" instruction. This field is genuinely supported by the
// Finance API (CreateExpenseAutomatedDto.isRecurring,
// FinanceExpenseService.create() creates a real RecurringTemplate when
// true) -- v1 of this Handler never extracted or forwarded it even though
// the backend already supported it; v2 (this file, and
// expense-extraction.v2.md) closes that gap.
const isRecurring = extracted.isRecurring === true;

if (!amountValid || !category) {
  const missingField = !amountValid ? 'amount' : 'category';
  return [{
    json: {
      ...context,
      extractionOutcome: 'needs_clarification',
      missingField,
      amount: amountValid ? amount : null,
      category,
      paymentMethod,
      date,
      description,
      isRecurring,
    },
  }];
}

return [{
  json: {
    ...context,
    extractionOutcome: 'valid',
    amount,
    category,
    paymentMethod,
    date,
    description,
    isRecurring,
  },
}];

// Converges both non-success extraction outcomes into the Response
// Contract (ADR-0008 Decision 2) -- kept as one node, not two branches,
// since both paths build the same shape with a different status/message;
// avoids an unnecessary extra IF node for two mutually exclusive Code
// paths already distinguished by "Validate Expense Extraction".
const v = $json;

if (v.extractionOutcome === 'needs_clarification') {
  const question = v.missingField === 'amount'
    ? 'How much did you spend?'
    : 'What category should I use for this expense -- one of: HOUSING, FOOD, UTILITIES, TRANSPORTATION, SHOPPING, MEDICAL, CREDIT_CARD, SAVINGS, TAX, OTHERS?';

  return [{
    json: {
      contractVersion: '1',
      workflowExecutionId: v.workflowExecutionId,
      status: 'clarify',
      intent: 'CREATE_EXPENSE',
      message: question,
      data: null,
      clarifyingQuestion: question,
    },
  }];
}

// extractionOutcome === 'extraction_failed' -- a system/model reliability
// failure (Ollama unreachable, or its output wasn't parseable JSON at
// all), never exposed in detail to the user -- no Ollama internals, no
// stack traces, matching this workflow's Failure Handling scope.
return [{
  json: {
    contractVersion: '1',
    workflowExecutionId: v.workflowExecutionId,
    status: 'error',
    intent: 'CREATE_EXPENSE',
    message: 'Sorry, I couldn\'t read the details of that expense. Could you try rephrasing it, e.g. "spent $12.50 on lunch"?',
    data: null,
    clarifyingQuestion: null,
  },
}];

// Assembles the Eyan Finance Service API's CreateExpenseAutomatedDto
// exactly (eyan-ai-platform backend/src/dto/finance-automation.dto.ts,
// finance-automation.validator.ts, ADR-0024 Decisions 2 & 6). amount is
// sent as a STRING, not a number -- finance-automation.validator.ts
// validates it with isFloat() but never .toFloat()s it, matching
// finance-expense.validator.ts's own comment: "money stays a string all
// the way to Prisma's Decimal field." workflowExecutionId is the value
// this Handler RECEIVED from the Router, forwarded unchanged -- never
// $execution.id (ADR-0008 Decision 4 / finance-inbox-contract.md's
// "Generating workflowExecutionId" section: regenerating it at any hop
// breaks the Finance API's idempotency check, eyan-ai-platform ADR-0024
// Decision 5). workflowName identifies THIS workflow, matching the
// pattern workflows/crm/03-ai-qualification.json's "Call AI Core" already
// established (each hop names itself on its own outbound call; only
// workflowExecutionId is the one constant thread).
const v = $json;

const body = {
  contractVersion: v.contractVersion,
  workflowExecutionId: v.workflowExecutionId,
  workflowName: '10-handle-create-expense',
  date: v.date,
  amount: String(v.amount),
  category: v.category,
  source: {
    channel: v.channel,
    externalUserId: v.externalUserId,
  },
  intent: 'CREATE_EXPENSE',
};

if (v.paymentMethod) body.paymentMethod = v.paymentMethod;
if (v.description) body.description = v.description;
if (v.isRecurring === true) body.isRecurring = true;
if (v.externalMessageId) body.source.externalMessageId = v.externalMessageId;
if (typeof v.startedAt === 'number') body.durationMs = Date.now() - v.startedAt;

return [{ json: { financeApiRequestBody: body, workflowExecutionId: v.workflowExecutionId } }];

// Maps the Eyan Finance Service API's response onto the Response Contract
// (ADR-0008 Decision 2). Success shape: ApiResponse.success wraps as
// {success:true, message, data} (eyan-ai-platform
// backend/src/utils/api-response.ts). data is either
// {replayed:true, workflowExecutionId} (a safe replay -- ADR-0024 Decision
// 5's known gap: a replay can't re-return the original expense, only
// confirm it already happened) or {replayed:false, id, date, amount,
// category, paymentMethod, description, ...} (finance-expense.mapper.ts's
// ExpenseResponseDto). Validation failures (400, express-validator) and
// auth/config failures (401/500) share the {success:false, ...} shape
// (validation.middleware.ts / service-auth.middleware.ts) -- never exposed
// to the user verbatim: no stack traces, no HTTP internals, no raw
// error/validator text, matching this workflow's Failure Handling scope.
const context = $('Build Finance API Request').item.json;
const result = $json;

function errorResponse(message) {
  return [{
    json: {
      contractVersion: '1',
      workflowExecutionId: context.workflowExecutionId,
      status: 'error',
      intent: 'CREATE_EXPENSE',
      message,
      data: null,
      clarifyingQuestion: null,
    },
  }];
}

if (result && result.error) {
  const message = String((result.error && result.error.message) || result.error);
  console.log(`[Validate Finance API Response] Finance API call failed: ${message}`);
  return errorResponse("Sorry, I couldn't save that expense right now. Please try again in a moment.");
}

if (!result || result.success !== true || !result.data) {
  const detail = result && Array.isArray(result.errors) ? JSON.stringify(result.errors) : JSON.stringify(result);
  console.log(`[Validate Finance API Response] Finance API rejected the request: ${detail}`);
  return errorResponse("Sorry, that expense couldn't be saved -- please check the amount and category and try again.");
}

const data = result.data;

if (data.replayed) {
  return [{
    json: {
      contractVersion: '1',
      workflowExecutionId: context.workflowExecutionId,
      status: 'success',
      intent: 'CREATE_EXPENSE',
      message: 'This expense was already logged -- no duplicate created.',
      data: { replayed: true },
      clarifyingQuestion: null,
    },
  }];
}

const amountText = typeof data.amount === 'string' ? data.amount : String(data.amount);

return [{
  json: {
    contractVersion: '1',
    workflowExecutionId: context.workflowExecutionId,
    status: 'success',
    intent: 'CREATE_EXPENSE',
    message: `Logged $${amountText} to ${data.category}.`,
    data: {
      id: data.id,
      date: data.date,
      amount: data.amount,
      category: data.category,
      paymentMethod: data.paymentMethod,
      description: data.description,
      isRecurring: data.isRecurring,
    },
    clarifyingQuestion: null,
  },
}];
